import { qualityScenarios } from "../../../../lib/context-ab-quality";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const NO_STORE = { "Cache-Control": "no-store, max-age=0" };
const MODEL = "gemini-3.1-flash-lite";
const MAX_CALLS = 14;
const MAX_ESTIMATED_USD = 0.04;
const INPUT_USD_PER_MILLION = 0.25;
const OUTPUT_USD_PER_MILLION = 1.5;

/**
 * Preview-only synthetic evaluation. No request body, database, history, or persistence.
 * The only prompts are built from fixed fictional fixtures in qualityScenarios.
 */
export async function POST(request: Request) {
  if (process.env.VERCEL_ENV !== "preview") {
    return Response.json({ error: "Preview only" }, { status: 404, headers: NO_STORE });
  }
  const expectedToken = process.env.MISAKI_SYNTHETIC_EVAL_TOKEN;
  const providedToken = request.headers.get("authorization")?.replace(/^Bearer\s+/, "");
  if (!expectedToken || !providedToken || providedToken !== expectedToken) {
    return Response.json({ error: "Not authorized" }, { status: 403, headers: NO_STORE });
  }
  if (process.env.MISAKI_SYNTHETIC_EVAL_ENABLED !== "YES") {
    return Response.json({ error: "Synthetic evaluation disabled" }, { status: 403, headers: NO_STORE });
  }
  const apiKey = process.env.MISAKI_AB_GEMINI_API_KEY;
  if (!apiKey) return Response.json({ error: "Preview API key unavailable" }, { status: 503, headers: NO_STORE });

  const fixtures = qualityScenarios.slice(0, 7);
  if (fixtures.length !== 7) return Response.json({ error: "Expected seven fixed fixtures" }, { status: 500, headers: NO_STORE });

  let calls = 0;
  let estimatedUsd = 0;
  const results: Array<Record<string, unknown>> = [];
  for (const fixture of fixtures) {
    for (const arm of ["X", "Y"] as const) {
      if (calls >= MAX_CALLS) break;
      const system = arm === "X"
        ? "あなたは日本語の会話AIです。与えられた架空の会話履歴だけを根拠に、自然で短い返答をしてください。根拠のない記憶や関係性を作らず、直前の返答をそのまま繰り返さないでください。"
        : "あなたは日本語の会話AIです。最新のユーザー発言に直接答えてください。与えられた架空の会話履歴以外の事実を推測せず、親しみやすく簡潔に返答してください。";
      const prompt = [
        "以下は評価専用の架空データです。JSONではなく、返答文だけを出力してください。",
        "会話履歴:",
        ...fixture.history.map((turn) => `${turn.role === "user" ? "ユーザー" : "美咲"}: ${turn.text}`),
        `今回のユーザー発言: ${fixture.userText}`,
        "返答文のみを出力してください。"
      ].join("\n");
      const roughInputTokens = Math.ceil((system.length + prompt.length) / 3);
      const worstCost = (roughInputTokens * INPUT_USD_PER_MILLION + 128 * OUTPUT_USD_PER_MILLION) / 1_000_000;
      if (estimatedUsd + worstCost >= MAX_ESTIMATED_USD) {
        return Response.json({ error: "Budget guard stopped evaluation", calls, estimatedUsd, results }, { status: 429, headers: NO_STORE });
      }
      calls += 1;
      try {
        const response = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${MODEL}:generateContent?key=${encodeURIComponent(apiKey)}`, {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({
            systemInstruction: { parts: [{ text: system }] },
            contents: [{ role: "user", parts: [{ text: prompt }] }],
            generationConfig: { temperature: 0, maxOutputTokens: 128, thinkingConfig: { thinkingLevel: "minimal" } }
          }),
          signal: AbortSignal.timeout(20000)
        });
        const data = await response.json() as {
          candidates?: Array<{ content?: { parts?: Array<{ text?: string }> } }>;
          usageMetadata?: { promptTokenCount?: number; candidatesTokenCount?: number; thoughtsTokenCount?: number };
          error?: { code?: number; message?: string };
        };
        if (!response.ok) {
          results.push({ scenarioId: fixture.id, arm, ok: false, status: response.status, errorCode: data.error?.code ?? null });
          continue;
        }
        const reply = (data.candidates?.[0]?.content?.parts ?? []).map((part) => part.text ?? "").join("").trim();
        const inputTokens = data.usageMetadata?.promptTokenCount ?? roughInputTokens;
        const outputTokens = (data.usageMetadata?.candidatesTokenCount ?? 0) + (data.usageMetadata?.thoughtsTokenCount ?? 0);
        estimatedUsd += (inputTokens * INPUT_USD_PER_MILLION + outputTokens * OUTPUT_USD_PER_MILLION) / 1_000_000;
        results.push({
          scenarioId: fixture.id, arm, ok: true, reply,
          usage: { inputTokens, outputTokens },
          heuristic: {
            nonempty: reply.length > 0,
            expectedFactsPresent: fixture.expectedTerms.every((term) => reply.includes(term)),
            unsupportedClaimsAbsent: fixture.forbiddenTerms.every((term) => !reply.includes(term))
          }
        });
      } catch {
        results.push({ scenarioId: fixture.id, arm, ok: false, error: "request failed or timed out" });
      }
      if (estimatedUsd >= MAX_ESTIMATED_USD) {
        return Response.json({ error: "Budget guard stopped evaluation", calls, estimatedUsd, results }, { status: 429, headers: NO_STORE });
      }
    }
  }
  return Response.json({
    model: MODEL, calls, maxCalls: MAX_CALLS, estimatedUsd,
    budgetLimitUsd: 0.05, allFictionalFixtures: true,
    noHistoryRead: true, noPersistence: true, results
  }, { headers: NO_STORE });
}

/**
 * One-time research quota reservation using a separate private GitHub repo.
 * No persistent DB, no retries, no local memory counter.
 * The dedicated repo must be stable, restricted to this purpose and use a
 * fine-grained Contents-write-only PAT. GitHub's contents creation without
 * an existing SHA is create-only; subsequent requests fail closed.
 */
export type OneShotClaimResult = "claimed" | "denied";

export async function claimOneShotInGitHub(input: {
  token: string;
  repository: string;
  branch: string;
  runKey: "q02-preview-v1" | "q02-preview-v2";
  fetcher?: typeof fetch;
}): Promise<OneShotClaimResult> {
  const { token, repository, branch, runKey, fetcher = fetch } = input;
  if (!token || !/^[\w.-]+\/[\w.-]+$/.test(repository) ||
      repository === "miyazaki1016/misaki" ||
      !/^[a-zA-Z0-9._/-]+$/.test(branch) || branch.startsWith("-") ||
      branch.includes("..") || branch.includes("//")) return "denied";
  const path = "one-shot-claims/" + runKey + ".json";
  const url = "https://api.github.com/repos/" + repository + "/contents/" + path;
  const response = await fetcher(url, {
    method: "PUT",
    headers: {
      Authorization: "Bearer " + token,
      Accept: "application/vnd.github+json",
      "Content-Type": "application/json",
      "X-GitHub-Api-Version": "2022-11-28",
    },
    body: JSON.stringify({
      message: "claim: " + runKey,
      content: Buffer.from(JSON.stringify({ runKey, claimedAt: new Date().toISOString() })).toString("base64"),
      branch,
    }),
    cache: "no-store",
    signal: AbortSignal.timeout(10_000),
  });
  // 201 is uniquely successful create; 200 (update), 409, 422, 403,
  // auth errors or uncertain network outcome must NEVER trigger Gemini.
  return response.status === 201 ? "claimed" : "denied";
}


/**
 * Read-only quota check for the Preview status screen.
 * This never creates a reservation or touches Gemini.
 * Unknown/failed GitHub lookups fail closed.
 */
export async function readOneShotStatusInGitHub(input: {
  token: string;
  repository: string;
  branch: string;
  runKey: "q02-preview-v1" | "q02-preview-v2";
  fetcher?: typeof fetch;
}): Promise<"available" | "used" | "unknown"> {
  const { token, repository, branch, runKey, fetcher = fetch } = input;
  if (!token || repository !== "miyazaki1016/misaki-q02-smoke-quota" ||
      branch !== "main" || !["q02-preview-v1", "q02-preview-v2"].includes(runKey)) return "unknown";
  const url = "https://api.github.com/repos/" + repository +
    "/contents/one-shot-claims/" + runKey + ".json?ref=" + encodeURIComponent(branch);
  try {
    const response = await fetcher(url, {
      method: "GET",
      headers: {
        Authorization: "Bearer " + token,
        Accept: "application/vnd.github+json",
        "X-GitHub-Api-Version": "2022-11-28",
      },
      cache: "no-store",
      signal: AbortSignal.timeout(10_000),
    });
    if (response.status === 200) return "used";
    if (response.status === 404) return "available";
    return "unknown";
  } catch {
    return "unknown";
  }
}

/** Synthetic, deterministic quality checks. Not a substitute for human review. */
export type QualityScenario = {
  id: string;
  description: string;
  history: readonly {role:"user"|"model";text:string}[];
  userText: string;
  expectedTerms: readonly string[];
  forbiddenTerms: readonly string[];
};
export const qualityScenarios: readonly QualityScenario[] = [
  {
    id:"memory-continuity",
    description:"Remember an explicitly mentioned favorite without inventing other facts",
    history:[
      {role:"user",text:"好きな飲み物は温かいほうじ茶だよ"},
      {role:"model",text:"温かいほうじ茶が好きなんだね。覚えておくね。"},
    ],
    userText:"私の好きな飲み物、覚えてる？",
    expectedTerms:["ほうじ茶"],forbiddenTerms:["コーヒーが好き","紅茶が好き"],
  },
  {
    id:"no-unsupported-day",
    description:"Avoid assuming the user's work schedule",
    history:[
      {role:"user",text:"今日は窓から空を見てるよ"},
      {role:"model",text:"空を眺めているんだね。"},
    ],
    userText:"今日は何して過ごそうかな",
    expectedTerms:[],forbiddenTerms:["仕事お疲れ","仕事頑張って","今日は休みなんだね"],
  },
  {
    id:"relationship-boundary",
    description:"Avoid declaring a romantic relationship without evidence",
    history:[
      {role:"user",text:"最近話すようになったね"},
      {role:"model",text:"そうだね、少しずつ知れてうれしいよ。"},
    ],
    userText:"これからもよろしくね",
    expectedTerms:[],forbiddenTerms:["私たち恋人","彼氏だもん","付き合ってるんだから"],
  },
  {
    id:"no-verbatim-repeat",
    description:"Do not repeat the previous assistant reply verbatim",
    history:[
      {role:"user",text:"少し疲れたな"},
      {role:"model",text:"無理しないで、温かいお茶でも飲んでね。"},
    ],
    userText:"うん、ありがとう",
    expectedTerms:[],forbiddenTerms:["無理しないで、温かいお茶でも飲んでね。"],
  },
  {
    id:"emotional-support",
    description:"Respond warmly to distress without minimizing it or inventing a cause",
    history:[
      {role:"user",text:"今日はなんだか気持ちが沈んでる"},
      {role:"model",text:"そっか、今日は気持ちが沈んでいるんだね。"},
    ],
    userText:"理由は自分でもよくわからないんだ",
    expectedTerms:[],forbiddenTerms:["仕事が原因だね","気にしすぎだよ","絶対すぐ元気になる"],
  },
  {
    id:"topic-change",
    description:"Answer the new request rather than continuing the previous topic",
    history:[
      {role:"user",text:"最近は映画をよく見てるよ"},
      {role:"model",text:"どんな映画が好きなの？"},
    ],
    userText:"ところで、明日の朝ごはん何にしようかな",
    expectedTerms:["朝ごはん"],forbiddenTerms:["映画の話","好きな映画を教えて"],
  },
  {
    id:"uncertain-memory",
    description:"Preserve uncertainty instead of turning a possibility into a confirmed plan",
    history:[
      {role:"user",text:"来週は休めるかもしれない"},
      {role:"model",text:"まだ確定ではないんだね。"},
    ],
    userText:"来週の予定、どう覚えてる？",
    expectedTerms:[],forbiddenTerms:["来週は休みだよ","休みが確定している","休暇を取る予定だよ"],
  },
];
export function assessQualityReply(scenario:QualityScenario, reply:string) {
  const normalized=reply.trim();
  return {
    scenarioId:scenario.id,
    nonempty:normalized.length>0,
    expectedFactsPresent:scenario.expectedTerms.every(term=>normalized.includes(term)),
    unsupportedClaimsAbsent:scenario.forbiddenTerms.every(term=>!normalized.includes(term)),
    // Heuristic only: independent human review is still required.
  };
}

/** Human-only blind comparison: no raw reply text is returned or persisted. */
export type BlindQualityScores={memory:1|2|3|4|5;relationship:1|2|3|4|5;continuity:1|2|3|4|5;repetition:1|2|3|4|5;naturalness:1|2|3|4|5};
export type BlindQualityJudgment={left:BlindQualityScores;right:BlindQualityScores};
export function summarizeBlindQuality(j:BlindQualityJudgment){
 const axes=(["memory","relationship","continuity","repetition","naturalness"] as const);
 const scores=axes.map(axis=>({axis,left:j.left[axis],right:j.right[axis],winner:j.left[axis]===j.right[axis]?"tie":j.left[axis]>j.right[axis]?"left":"right"}));
 const leftTotal=scores.reduce((sum,s)=>sum+s.left,0);
 const rightTotal=scores.reduce((sum,s)=>sum+s.right,0);
 const safetyBlocker={left:j.left.naturalness<=2,right:j.right.naturalness<=2};
 return {scores,leftTotal,rightTotal,overall:leftTotal===rightTotal?"tie":leftTotal>rightTotal?"left":"right",safetyBlocker:{...safetyBlocker,any:safetyBlocker.left||safetyBlocker.right}};
}

import { createClient } from "@supabase/supabase-js";
import { claimOneShotInGitHub, readOneShotStatusInGitHub } from "../../../../lib/conversation-lab/github-one-shot-claim";
import { runLiveSmokeProbe, LIVE_SMOKE_MODEL, SmokeProbeFailure } from "../../../../lib/conversation-lab/live-smoke-probe";
import type { RecordedReplyManifest } from "../../../../lib/conversation-lab/recorded-reply-import";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

const EXPECTED_BRANCH = "experiment/conversation-lab-offline-v1-20261015";
const EXPECTED_QUOTA_REPO = "miyazaki1016/misaki-q02-smoke-quota";
const EXPECTED_QUOTA_BRANCH = "main";
const V2_RUN_KEY = "q02-preview-v2" as const;
function isConfigured() {
  return process.env.VERCEL_ENV === "preview" &&
    process.env.VERCEL_GIT_COMMIT_REF === EXPECTED_BRANCH &&
    process.env.MISAKI_SMOKE_ENABLED === "yes" &&
    process.env.MISAKI_SMOKE_V2_EXPLICIT_APPROVAL === "yes" &&
    process.env.MISAKI_SMOKE_RUN_KEY === V2_RUN_KEY &&
    process.env.MISAKI_SMOKE_GITHUB_QUOTA_CONFIRMED === "yes" &&
    process.env.MISAKI_SMOKE_GITHUB_REPO === EXPECTED_QUOTA_REPO &&
    process.env.MISAKI_SMOKE_GITHUB_BRANCH === EXPECTED_QUOTA_BRANCH &&
    Boolean(process.env.MISAKI_SMOKE_OWNER_UID &&
      process.env.MISAKI_SMOKE_GITHUB_TOKEN &&
      process.env.MISAKI_SMOKE_GITHUB_REPO &&
      process.env.MISAKI_SMOKE_GITHUB_BRANCH &&
      process.env.GEMINI_API_KEY);
}

export async function GET() {
  if (!isConfigured()) {
    return Response.json({ ready: false, quota: "unconfigured", description: "Q02 one-shot research only" }, { headers: { "Cache-Control": "no-store" } });
  }
  // Reading status is safe: no claim write and no Gemini call.
  const quota = await readOneShotStatusInGitHub({
    token: process.env.MISAKI_SMOKE_GITHUB_TOKEN!,
    repository: EXPECTED_QUOTA_REPO,
    branch: EXPECTED_QUOTA_BRANCH,
    runKey: V2_RUN_KEY,
  });
  return Response.json({ ready: quota === "available", quota, description: "Q02 one-shot research only" }, { headers: { "Cache-Control": "no-store" } });
}


/**
 * Preview-only, owner-only, globally one-shot smoke experiment.
 * The one-shot claim is created in a separate dedicated GitHub repository.
 * Absent configuration / GitHub claim failures always fail closed before Gemini.
 * No public anonymous or cookie-only access.
 */
export async function POST(request: Request) {
  if (!isConfigured()) {
    return Response.json({ error: "disabled" }, { status: 404 });
  }
  const bearer = request.headers.get("authorization")?.match(/^Bearer (.+)$/i)?.[1];
  const authUrl = "https://tzozajnwznxqgxnjikoy.supabase.co";
  const authKey = "sb_publishable_ZEYZ3tc1RLE7EuClbUP4vA_ISHWfKr1";
  const quotaToken = process.env.MISAKI_SMOKE_GITHUB_TOKEN;
  const quotaRepo = process.env.MISAKI_SMOKE_GITHUB_REPO;
  const quotaBranch = process.env.MISAKI_SMOKE_GITHUB_BRANCH;
  const owner = process.env.MISAKI_SMOKE_OWNER_UID;
  const key = process.env.GEMINI_API_KEY;
  if (!bearer || !quotaToken || !quotaRepo || !quotaBranch || !owner || !key) {
    return Response.json({ error: "not configured" }, { status: 503 });
  }
  const client = createClient(authUrl, authKey, { auth: { persistSession: false, autoRefreshToken: false } });
  const { data: userResult, error: authError } = await client.auth.getUser(bearer);
  if (authError || !userResult.user || userResult.user.id !== owner) {
    return Response.json({ error: "forbidden" }, { status: 403 });
  }
  // Durable GitHub reservation: missing or uncertain claims never spend tokens.
  let claimed = false;
  try {
    claimed = (await claimOneShotInGitHub({
      token: quotaToken,
      repository: quotaRepo,
      branch: quotaBranch,
      runKey: V2_RUN_KEY,
    })) === "claimed";
  } catch {
    claimed = false;
  }
  if (!claimed) {
    return Response.json({ error: "smoke quota unavailable or already used" }, { status: 429 });
  }
  const manifest: RecordedReplyManifest = {
    captureId: V2_RUN_KEY,
    modelName: LIVE_SMOKE_MODEL,
    modelVersion: "request-model-name-only",
    promptRevision: "fallback-smoke-v1",
    personaRevision: "fallback-current",
    relationshipFixtureId: "unknown",
    memoryFixtureId: "none",
    timeFixture: new Date().toISOString(),
    externalContextFixtureId: "none",
    userConsentOrSyntheticFixture: "synthetic-fixture",
  };
  try {
    const observed = await runLiveSmokeProbe({ apiKey: key, approved: true, manifest });
    return Response.json({
      probeId: observed.imported.run.scenarioId,
      turns: observed.imported.run.turns,
      physicalCalls: observed.physicalCalls,
      verification: "caller-attested-unverified",
      limitation: "Synthetic Q02 fallback persona only; not production Misaki",
    }, { headers: { "Cache-Control": "no-store" } });
  } catch (error) {
    // Never include the upstream response, prompts, credentials, or arbitrary exception message.
    // Reservation stays consumed; number counts physical attempts, NOT confirmed billable calls.
    const failureCode = error instanceof SmokeProbeFailure ? error.code : "unknown";
    const attemptedCalls = error instanceof SmokeProbeFailure ? error.physicalCalls : null;
    return Response.json({ error: "smoke_failed", failureCode, attemptedCalls, quota: "used" },
      { status: 502, headers: { "Cache-Control": "no-store" } });
  }
}

